<?php require 'includes/db.php'; require 'includes/auth.php'; $pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)($_POST['product_id']??0);$q=max(1,(int)($_POST['quantity']??1));if(isset($_POST['add'])){$_SESSION['cart'][$id]=($_SESSION['cart'][$id]??0)+$q;}if(isset($_POST['remove']))unset($_SESSION['cart'][$id]);header('Location: cart.php');exit;}
$cart=$_SESSION['cart']??[];$rows=[];$total=0;foreach($cart as $id=>$q){$s=$pdo->prepare('SELECT * FROM products WHERE id=?');$s->execute([$id]);if($p=$s->fetch()){$p['quantity']=$q;$p['subtotal']=$q*$p['price'];$total+=$p['subtotal'];$rows[]=$p;}}
require 'includes/header.php';?><h1>Your Cart</h1><?php if(!$rows):?><div class="notice">Your cart is empty. <a href="shop.php">Go to shop</a>.</div><?php else:?><div class="table-wrap"><table><tr><th>Item</th><th>Qty</th><th>Subtotal</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=$r['quantity']?></td><td>₹<?=number_format($r['subtotal'],2)?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="product_id" value="<?=$r['id']?>"><button name="remove" class="linkbtn">Remove</button></form></td></tr><?php endforeach;?></table></div><h2>Total: ₹<?=number_format($total,2)?></h2><a class="btn" href="checkout.php">Checkout</a><?php endif; require 'includes/footer.php';?>